@push('scripts')<script>const dateInput=document.querySelector('#tanggal_sesi');const slots=document.querySelector('#slots');const selected=document.querySelector('#jam_mulai');dateInput?.addEventListener('change',async()=>{slots.innerHTML='<p class="col-span-full p-5 text-center text-slate-500">Memuat slot...</p>';const draft=@json($draft);const url=`{{ route('booking.slots') }}?id_room=${draft.id_room}&id_package=${draft.id_package}&tanggal_sesi=${dateInput.value}`;const response=await fetch(url);const result=await response.json();slots.innerHTML='';if(!result.success||!result.data?.length){slots.innerHTML='<p class="col-span-full rounded-xl bg-amber-50 p-5 text-center text-amber-700">Tidak ada slot kosong pada tanggal ini.</p>';return;}result.data.forEach(slot=>{const time=typeof slot==='string'?slot:(slot.jam_mulai??slot.time);const button=document.createElement('button');button.type='button';button.textContent=time;button.className='rounded-xl border border-slate-200 bg-white p-4 font-bold hover:border-black';button.onclick=()=>{selected.value=time;document.querySelectorAll('#slots button').forEach(item=>item.classList.remove('bg-black','text-white'));button.classList.add('bg-black','text-white')};slots.appendChild(button);});});</script>@endpush
